    if (f.rolling) return f.moves.find((m) => m.id === f.rolling.id) ?? null;
    if (f.bide) return f.moves.find((m) => m.id === "bide") ?? null;
    return f.charging ? f.moves.find((m) => m.id === f.charging) ?? null : null;
