// The Kanto League is wider than a Bedrock structure can be, so worldgen places only a seed of it (port.py's
// create_gyms): a gym-sized corner of its bottom layers with anchor blocks in them. The first random tick of an anchor
// places every tile of the League over the seed. A structure placed into chunks that are not ticking is silently left
// out, so a ticking area holds the League's chunks while the tiles go in; each tile is checked by a block of its own,
// the first tile (which covers the anchors, putting their own blocks back) last, and a later tick retries what failed.
const leagueBuilding = new Set();   // "x y z" of each League being placed
function completeLeague(block) {
    const a = GYM_LEAGUE?.anchors[block.permutation.getState("cobblemon:anchor")];
    if (!a) return;
    const o = { x: block.x - a[0], y: block.y - a[1], z: block.z - a[2] }, dim = block.dimension, key = `${o.x} ${o.y} ${o.z}`;
    if (leagueBuilding.has(key)) return;
    leagueBuilding.add(key);
    const [sx, sy, sz] = GYM_LEAGUE.size, area = `cbl_${o.x}_${o.z}`.replace(/-/g, "m");
    try { dim.runCommand(`tickingarea add ${o.x} ${o.y} ${o.z} ${o.x + sx - 1} ${o.y + sy - 1} ${o.z + sz - 1} ${area}`); } catch (e) { }
    system.runTimeout(() => {
        try {
            for (const [id, dx, dz, px, py, pz, probe] of GYM_LEAGUE.tiles) {
                const at = dim.getBlock({ x: o.x + px, y: o.y + py, z: o.z + pz });
                if (at?.typeId === probe) continue;   // placed already
                world.structureManager.place(id, dim, { x: o.x + dx, y: o.y, z: o.z + dz }, { includeEntities: false });
                if (dim.getBlock({ x: o.x + px, y: o.y + py, z: o.z + pz })?.typeId !== probe) throw new Error(`${id} did not land`);
            }
            // the League's Shopkeeper, a CobbleDollars merchant in RGS's structure: the Poke Mart clerk, held in place as in the hub
            for (const [x, y, z, name] of GYM_LEAGUE.npcs ?? []) {
                const at = { x: o.x + x + 0.5, y: o.y + y, z: o.z + z + 0.5 };
                if (dim.getEntities({ type: "cobblemon:poke_mart_clerk", location: at, maxDistance: 2 }).length) continue;
                const clerk = dim.spawnEntity("cobblemon:poke_mart_clerk", at);
                clerk.nameTag = name || "Shopkeeper"; clerk.addTag("poke_mart_clerk");
                // the Shopkeeper's own stock, Radical Gyms' CobbleDollars offers as emeralds (gyms.js)
                if (GYM_LEAGUE.shop?.length) try { clerk.setDynamicProperty("cobblemon:shop", JSON.stringify(GYM_LEAGUE.shop)); } catch (e) { }
                clerk.addEffect("slowness", 20000000, { amplifier: 255, showParticles: false });
            }
            // the League's display cases filled with Radical Gyms' medicine, and its box kept mob-free (rct_world.js)
            rctNoteLeague(dim, o, setCaseItem);
        } catch (e) { console.warn(`league at ${key}: ${e}`); }
        try { dim.runCommand(`tickingarea remove ${area}`); } catch (e) { }
        leagueBuilding.delete(key);
    }, 60);
}

// RCT's Trainer Card (TrainerCard.java, TrainerCardScreen, TargetArrowRenderer). Used, it opens the card: the player's
// level cap, how many gym trainers they have beaten, and those trainers in order of their teams' level, a beaten one by
// name, the next one to beat hidden as RCT hides its key trainer, the rest as "???"; picking a beaten or next one shows
// its type, the level cap it needs and gives, and who must be beaten first. Held, it points at the next trainer the
// player can battle, if one is loaded (RCT draws a small arrow over the card in the hand; here an arrow over the hotbar),
// spinning when that trainer is in another dimension. A trainer only stands in its gym once a player steps on the
