    let best, bestD = Infinity;
    const consider = (dim, x, z) => {
        const d = dim === player.dimension.id ? Math.hypot(x - player.location.x, z - player.location.z) : Infinity;
        if (!best || d < bestD) { best = { dim, x, z }; bestD = d; }
    };
