function takeItem(player, typeId, count) {
    const inv = player.getComponent(EntityComponentTypes.Inventory)?.container;
    for (let i = 0; inv && i < inv.size && count > 0; i++) {
        const it = inv.getItem(i);
        if (it?.typeId !== typeId) continue;
        const n = Math.min(count, it.amount);
        count -= n;
        if (it.amount === n) inv.setItem(i, undefined); else { it.amount -= n; inv.setItem(i, it); }
    }
}
// a spot 25 to 70 blocks off along each axis, either way, on the ground, as nextPos picks it
function associationSpot(player) {
    const dim = player.dimension, { x: px, y: py, z: pz } = player.location;
    for (let tries = 0; tries < 8; tries++) {
        const off = () => (TA_MIN + Math.floor(Math.random() * (TA_MAX - TA_MIN))) * (Math.random() < 0.5 ? -1 : 1);
        const x = Math.floor(px) + off(), z = Math.floor(pz) + off();
        for (let y = Math.floor(py) + TA_VERTICAL; y >= Math.floor(py) - TA_VERTICAL; y--) {
            let ground, feet, head;
            try { ground = dim.getBlock({ x, y, z }); feet = ground?.above(); head = feet?.above(); } catch (e) { break; }
            if (!ground || !feet || !head) continue;
            if (ground.isAir || ground.isLiquid || !feet.isAir || !head.isAir) continue;
            return { x: x + 0.5, y: y + 1, z: z + 0.5 };
        }
    }
    return undefined;
}
// in a village (StructureRequirement's #minecraft:village): within VILLAGE_RADIUS of one the script has found, or of a
// bell in the Overworld
function villageAt(dim, at) {
    if (dim.id !== "minecraft:overworld") return false;
    if (pokecenterSites().some(([x, z]) => Math.hypot(x - at.x, z - at.z) < VILLAGE_RADIUS)) return true;
    try {
        const volume = new BlockVolume({ x: at.x - VILLAGE_RADIUS, y: at.y - 16, z: at.z - VILLAGE_RADIUS }, { x: at.x + VILLAGE_RADIUS, y: at.y + 16, z: at.z + VILLAGE_RADIUS });
        return dim.getBlocks(volume, { includeTypes: ["minecraft:bell"] }, true).getCapacity() > 0;
    } catch (e) { return false; }
}
function nearVillage(player) {
    const dim = player.dimension, at = player.location;
    if (dim.getEntities({ type: "minecraft:villager_v2", location: at, maxDistance: 48 }).length < 3) return false;
    try {
        const volume = new BlockVolume({ x: at.x - 48, y: at.y - 16, z: at.z - 48 }, { x: at.x + 48, y: at.y + 16, z: at.z + 48 });
        return dim.getBlocks(volume, { includeTypes: ["minecraft:bell"] }, true).getCapacity() > 0;
    } catch (e) { return false; }
}
function spawnAssociation(player, sentTo) {
    const spot = associationSpot(player);
    if (!spot) return false;
    let ta;
    try { ta = player.dimension.spawnEntity(TA, spot); } catch (e) { return false; }
    ta.nameTag = RCT_TEXT["entity.rctmod.trainer_association"] ?? "Trainer Association";
    if (sentTo) {
        try { ta.getComponent(EntityComponentTypes.Tameable)?.tame(player); ta.triggerEvent("cobblemon:follow"); } catch (e) { }
        taFor.set(player.id, ta.id);
    }
    return true;
}
system.runInterval(() => {
    for (const player of world.getPlayers()) {
        // in any dimension, as RCT's spawns (canSpawnNearby, with no dimension blacklisted)
        const near = player.dimension.getEntities({ type: TA, location: player.location, maxDistance: TA_MAX });
        if (near.length) continue;
        const sent = taFor.get(player.id) && world.getEntity(taFor.get(player.id));
        if (!sent) taFor.delete(player.id);
        if (nearVillage(player)) spawnAssociation(player, false);
        else if (!sent && hasCard(player) && (!rctSeries(player) || rctSeriesDone(player))) spawnAssociation(player, true);
    }
}, TA_SPAWN_TICKS);
system.runInterval(() => {
    for (const ta of ["overworld", "nether", "the_end"].flatMap((d) => { try { return world.getDimension(d).getEntities({ type: TA }); } catch (e) { return []; } })) {
        const near = ta.dimension.getPlayers({ location: ta.location, maxDistance: TA_DESPAWN_DISTANCE }).length > 0;
        const idle = near ? 0 : (taIdle.get(ta.id) ?? 0) + 20;
        if (idle >= TA_DESPAWN_TICKS) { taIdle.delete(ta.id); try { ta.remove(); } catch (e) { } continue; }
        taIdle.set(ta.id, idle);
    }
}, 20);
// the Association's item offer, rolled once per Association and kept on it: emeralds and apricorns for a Trainer Card
function associationOffer(ta) {
    let offer;
    try { offer = JSON.parse(ta.getDynamicProperty(TA_OFFER) ?? "null"); } catch (e) { }
    if (!offer) {
        const between = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
        offer = { emeralds: between(1, 8), apricorn: APRICORNS[between(0, APRICORNS.length - 1)], apricorns: between(1, 5), max: between(2, 4), used: 0, restock: 0 };
    }
    if (offer.used > 0 && system.currentTick >= offer.restock) { offer.used = 0; offer.restock = 0; }
    ta.setDynamicProperty(TA_OFFER, JSON.stringify(offer));
    return offer;
}
const stars = (n, m = 10) => "\u2605".repeat(Math.floor(Math.min(n, m) / 2)) + (n % 2 ? "\u2bea" : "") + "\u2606".repeat(Math.floor((m - Math.min(n, m)) / 2));
// the series a player may start here (TrainerAssociation.updateOffersFor): not the one they are in; Freeroam only once
// a series is completed (freeroamRequiresCompletedSeries); in Freeroam, only the series they paused
function associationSeries(player) {
    const current = rctSeries(player), completed = jsonProp(player, RCT_COMPLETED, {});
    return Object.keys(RCT_SERIES_DATA).filter((sid) => sid !== current)
        .filter((sid) => sid !== "freeroam" || Object.values(completed).some((n) => n > 0))
        .filter((sid) => current !== "freeroam" || !player.getDynamicProperty(RCT_PREVIOUS) || sid === player.getDynamicProperty(RCT_PREVIOUS))
        .filter((sid) => RCT_SERIES_DATA[sid].requiredSeries.every((group) => group.some((r) => (completed[r] ?? 0) > 0)));
}
function showAssociation(player, ta) {
    const offer = associationOffer(ta), series = associationSeries(player);
    const t = (k) => RCT_TEXT[k] ?? k;
    const emeraldLeft = offer.max - offer.used;
    const apricornName = offer.apricorn.split(":")[1].replace("_", " ").replace(/\b\w/g, (c) => c.toUpperCase());
    const form = new ActionFormData().title(t("entity.rctmod.trainer_association"));
    const actions = [];
    form.button(`Trainer Card\n${offer.emeralds} Emerald, ${offer.apricorns} ${apricornName}${emeraldLeft > 0 ? "" : " (sold out)"}`, "textures/items/rct/trainer_card");
    actions.push(() => {
        if (emeraldLeft <= 0) { player.sendMessage("§7The Trainer Association has no more cards for now."); return; }
        if (countItem(player, "minecraft:emerald") < offer.emeralds || countItem(player, offer.apricorn) < offer.apricorns) {
            player.sendMessage(`§7You need ${offer.emeralds} Emerald and ${offer.apricorns} ${apricornName}.`); return;
        }
        takeItem(player, "minecraft:emerald", offer.emeralds); takeItem(player, offer.apricorn, offer.apricorns);
        player.getComponent(EntityComponentTypes.Inventory)?.container?.addItem(new ItemStack(CARD, 1));
        offer.used++;
        if (!offer.restock) offer.restock = system.currentTick + 6000 + Math.floor(Math.random() * 18000);
        ta.setDynamicProperty(TA_OFFER, JSON.stringify(offer));
    });
    for (const sid of series) {
        const data = RCT_SERIES_DATA[sid];
        form.button(`${data.title}\n${sid === "freeroam" ? "" : stars(data.difficulty)}`, "textures/items/rct/trainer_card");
        actions.push(() => showSeriesOffer(player, ta, sid));
    }
    if (!series.length) form.body("§7There is no other series for you to start right now.");
    form.show(player).then((r) => { if (!r.canceled) actions[r.selection]?.(); }).catch(() => { });
}
function showSeriesOffer(player, ta, sid) {
    const data = RCT_SERIES_DATA[sid], t = (k) => RCT_TEXT[k] ?? k;
    const completed = jsonProp(player, RCT_COMPLETED, {})[sid] ?? 0;
    const resuming = rctSeries(player) === "freeroam" && player.getDynamicProperty(RCT_PREVIOUS) === sid;
    const body = [data.description, ""];
    if (sid !== "freeroam") {
        body.push(`${t("gui.rctmod.trainer_association.difficulty")}: ${stars(data.difficulty)}`, `${t("gui.rctmod.trainer_association.completed")}: ${completed}`, "");
        body.push(resuming ? `§6${t("gui.rctmod.trainer_association.series_continue")}` : `§l§6${t("gui.rctmod.trainer_association.important")}§r\n§6${t("gui.rctmod.trainer_association.series_reset")}`);
    }
    new MessageFormData().title(data.title).body(body.join("\n") + "\n\n§7Costs one Trainer Card.")
        .button1("Not now").button2(sid === "freeroam" ? "Take a break" : resuming ? "Continue" : "Start")
        .show(player).then((r) => {
            if (r.canceled || r.selection !== 1) return;
            if (!hasCard(player)) { player.sendMessage("§7You need a Trainer Card to start a series."); return; }
            // the card is taken and given back named for the series (SeriesSwitchOffer)
            takeItem(player, countItem(player, CARD) > 0 ? CARD : CARD_GLINT, 1);
            const card = new ItemStack(CARD, 1);
            card.nameTag = data.title;
            try { card.setLore([data.description]); } catch (e) { }
            player.getComponent(EntityComponentTypes.Inventory)?.container?.addItem(card);
            const before = rctSeries(player);
            if (sid === "freeroam") {
                player.setDynamicProperty(RCT_PREVIOUS, before);
            } else if (!resuming) {
                player.setDynamicProperty(RCT_DEFEATS, undefined);   // a new series starts from nothing
            }
            player.setDynamicProperty(RCT_SERIES, sid);
            const title = sid === "freeroam" ? "gui.rctmod.title.series_paused" : resuming ? "gui.rctmod.title.series_continued" : "gui.rctmod.title.series_started";
            try { player.onScreenDisplay.setTitle(t(title), { subtitle: RCT_SERIES_DATA[sid === "freeroam" ? before : sid]?.title ?? data.title, fadeInDuration: 10, stayDuration: 60, fadeOutDuration: 20 }); } catch (e) { }
            // the one sent to this player has done its job: it stops following them
            if (taFor.get(player.id) === ta.id) { try { ta.triggerEvent("cobblemon:stay"); } catch (e) { } taFor.delete(player.id); }
        }).catch(() => { });
}
world.beforeEvents.playerInteractWithEntity.subscribe((event) => {
    if (event.target?.typeId !== TA) return;
    event.cancel = true;
    const { player, target } = event;
    system.run(() => { if (target.isValid) showAssociation(player, target); });
});
system.runInterval(() => {
    for (const player of world.getPlayers()) {
        let held;
        try { held = player.getComponent(EntityComponentTypes.Equippable)?.getEquipment(EquipmentSlot.Mainhand)?.typeId; } catch (e) { }
        if (!isCard(held)) continue;
        const target = cardTarget(player);
        // TrainerCard.isFoil: the card glints while it has a target. A Bedrock item's glint is fixed, so the held card
        // is swapped for its glinting twin (rctmod:trainer_card_glint) and back, keeping its name and lore
        const want = target ? CARD_GLINT : CARD;
        if (held !== want) {
            try {
                const equip = player.getComponent(EntityComponentTypes.Equippable), old = equip?.getEquipment(EquipmentSlot.Mainhand);
                if (old) { const swap = new ItemStack(want, 1); swap.nameTag = old.nameTag; try { swap.setLore(old.getLore()); } catch (e) { } equip.setEquipment(EquipmentSlot.Mainhand, swap); }
            } catch (e) { }
        }
        if (!target) {
            // nothing to point at yet: no Association about for a player in no series, or no gym with a trainer to
            // battle near a player in one, who may be standing at a gym whose spot marker has not had its random tick yet
            if (rctSeries(player) && !rctSeriesDone(player)) scanForGyms(player);
            const line = rctSeries(player) && !rctSeriesDone(player) ? "§7No gym found yet. Explore: the card points to the next one you pass near."
                : "§7A Trainer Association will find you soon: keep the card on you.";
            try { player.onScreenDisplay.setActionBar(line); } catch (e) { }
            continue;
        }
        let arrow;
        if (target.dim !== player.dimension.id) arrow = ARROWS[Math.floor(system.currentTick / 5) % 8];
        else {
            const yaw = player.getRotation().y, dx = target.x - player.location.x, dz = target.z - player.location.z;
            const bearing = (Math.atan2(-dx, dz) * 180) / Math.PI;   // Minecraft yaw: 0 is south, 90 west
            arrow = ARROWS[(Math.round((((bearing - yaw) % 360) + 360) % 360 / 45)) % 8];
        }
        try { player.onScreenDisplay.setActionBar(`\u00a7c${arrow}`); } catch (e) { }
    }
}, 5);
// TrainerCardScreen: the trainers of the series, filtered by type with RCT's cycle button (All, then each TrainerType),
// a page of CARD_PAGE at a time since a series has hundreds; the card remembers the filter and page
const CARD_FILTERS = ["all", ...Object.keys(RCT_TYPES)], CARD_PAGE = 60;
const cardView = new Map();   // player id -> { filter, page }
function showTrainerCard(player) {
    const view = cardView.get(player.id) ?? { filter: "all", page: 0 }, defeats = rctDefeats(player), next = new Set(rctNext(player)), sid = rctSeries(player);
    const all = rctOrder(player), ids = all.filter((id) => view.filter === "all" || (RCT_TRAINERS[id].type ?? "normal") === view.filter);
    const pages = Math.max(1, Math.ceil(ids.length / CARD_PAGE)), page = Math.min(view.page, pages - 1), shown = ids.slice(page * CARD_PAGE, (page + 1) * CARD_PAGE);
    const total = Object.values(defeats).reduce((n, c) => n + c, 0);
    // no cap outside a series (rctLevelCap's 100); RCT's initial cap starts with the series
    const series = RCT_SERIES_DATA[sid];
    const cap = sid && sid !== "freeroam" ? `${rctLevelCap(player)}` : sid === "freeroam" ? "none (Freeroam)" : "none yet (choose a series at a Trainer Association)";
    const form = new ActionFormData().title("Trainer Card")
        .body(`\u00a7f${player.name}\n\u00a77Series: \u00a7f${series?.title ?? "No Series"}\n\u00a77Level Cap: \u00a7f${cap}\n\u00a77Total: \u00a7f${total}\n\u00a77Hold the card to point at your next trainer.`);
    // the cycle button shows the series' title for All (#313), else the type's name
    form.button(`\u00a78Type: \u00a7f${view.filter === "all" ? series?.title ?? "All" : RCT_TYPES[view.filter]?.name ?? view.filter}  \u00a77(${ids.length})`);
    const rows = shown.map((id) => {
        const n = defeats[id] ?? 0, key = next.has(id), t = RCT_TRAINERS[id];
        // RCT hides the next one in obfuscated text, which a Bedrock form shows as noise: here "???", marked as next,
        // the rest "???" with their type's symbol
        const name = n > 0 ? t.name : key ? `??? (next ${rctType(id)})` : `??? ${RCT_TYPES[t.type]?.symbol ?? ""}`.trimEnd();
        form.button(`${key ? "\u00a72" : n > 0 ? "\u00a70" : "\u00a78"}${name}  ${n > 0 ? n : ""}`);
        return id;
    });
    const extra = pages > 1 ? [["prev", `\u00a77Page ${page + 1} of ${pages}: previous`], ["next", "\u00a77Next page"]] : [];
    for (const [, label] of extra) form.button(label);
    form.show(player).then((r) => {
        if (r.canceled) return;
        if (r.selection === 0) { cardView.set(player.id, { filter: CARD_FILTERS[(CARD_FILTERS.indexOf(view.filter) + 1) % CARD_FILTERS.length], page: 0 }); return showTrainerCard(player); }
        const pick = r.selection - 1;
        if (pick >= rows.length) {
            const [what] = extra[pick - rows.length] ?? [];
            if (what) cardView.set(player.id, { filter: view.filter, page: (page + (what === "next" ? 1 : pages - 1)) % pages });
            return showTrainerCard(player);
        }
        const id = rows[pick];
        if (!(defeats[id] > 0) && !next.has(id)) {
            // a locked trainer: say so rather than redraw the card, which looked like the tap did nothing
            new ActionFormData().title("Trainer Card").body(`§f???\n§7Type: §f${rctType(id)}\n§7Beat the trainers before this one first.`)
                .button("Back").show(player).then((b) => { if (!b.canceled) showTrainerCard(player); }).catch(() => { });
            return;
        }
        const t = RCT_TRAINERS[id], missing = t.requires.filter((g) => !g.some((x) => !RCT_TRAINERS[x] || !rctInSeries(x, sid) || rctDone(player, x))).map((g) => g.map((x) => RCT_TRAINERS[x]?.name ?? x).join(" or "));
        const later = all.filter((x) => RCT_TRAINERS[x].requires.some((g) => g.includes(id))).map((x) => RCT_TRAINERS[x].level);
        // TrainerInfoWidget's pages: Overview (type, the cap it needs and gives, required trainers), Spawning (the biome
        // tags it spawns in and keeps out of, its signature item for a Trainer Spawner) and Team (once beaten)
        const spawning = `\n\u00a77Biomes: \u00a7f${t.biomes.length ? t.biomes.map(rctBiomeName).join(", ") : "anywhere"}${t.noBiomes.length ? ` \u00a77(not ${t.noBiomes.map(rctBiomeName).join(", ")})` : ""}`
            + (t.sig ? `\n\u00a77Signature Item: \u00a7f${itemName(t.sig)}` : "") + (t.swf <= 0 ? "\n\u00a77Found in its gym only" : "");
        new ActionFormData().title("Trainer Card")
            .body(`\u00a7f${defeats[id] > 0 ? t.name : "???"}\n\u00a77Type: \u00a7f${rctType(id)}\n\u00a77Level Cap: \u00a7f${Math.max(RCT_INITIAL_CAP, t.level)} -> ${later.length ? Math.max(RCT_INITIAL_CAP, Math.min(...later)) : 100}`
                + (missing.length ? `\n\u00a77Required Trainers:\n\u00a7f${missing.join("\n")}` : "") + spawning
                + (defeats[id] > 0 ? `\n\u00a77Team:\n\u00a7f${t.team.map((m) => `${REGIONAL[m.form] ?? ""}${POKEMON[m.t]?.name ?? m.t} Lv. ${m.lv}`).join("\n")}` : ""))
            .button("Back").show(player).then((b) => { if (!b.canceled) showTrainerCard(player); }).catch(() => { });
    }).catch(() => { });
}
// a gym trainer's death ends its battle at once (TrainerMob.cancelBattle, #113), the player's Pokemon kept as they are
world.afterEvents.entityDie.subscribe(({ deadEntity }) => {
    if (deadEntity?.typeId !== "cobblemon:rct_trainer") return;
    for (const b of [...battles.values()]) if (b.gym?.npc?.id === deadEntity.id) endBattle(b, "\u00a77The trainer is gone. The battle is over.");
});
// what rct_world.js needs from here: the party and its levels, the series, the cap, the progression and the battles
initRctWorld({
    party: (player) => summaryParty(player), levelOf: (e) => prop(e, LEVEL) ?? POKEMON[e.typeId]?.level ?? 1,
    series: rctSeries, levelCap: rctLevelCap, unlocked: rctUnlocked, next: rctNext, canBattle: gymCanBattle, startBattle: startGymBattle,
    inBattle: (npc) => [...battles.values()].some((b) => b.gym?.npc?.id === npc.id)
});
world.afterEvents.itemUse.subscribe(({ itemStack, source }) => {
    if (isCard(itemStack?.typeId) && source?.typeId === "minecraft:player") showTrainerCard(source);
});

// the markers' jobs (port.py's GYM_ROLES), when the plate or button above one is used
function gymMarker(block) {
    if (block?.typeId !== "cobblemon:gym_marker") return undefined;
    const p = block.permutation;
    return { block, role: p.getState("cobblemon:role"), trainer: p.getState("cobblemon:trainer"), rise: p.getState("cobblemon:rise") };
}
function findMarker(dimension, at, role, trainer, reach, height) {
    for (let r = 0; r <= reach; r++) {
        for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
            if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
            for (let dy = -height; dy <= height; dy++) {
                let m;
                try { m = gymMarker(dimension.getBlock({ x: at.x + dx, y: at.y + dy, z: at.z + dz })); } catch (e) { }
                if (m && m.role === role && m.trainer === trainer) return m;
            }
        }
    }
    return undefined;
}
function summonGymTrainer(marker) {
    const id = GYM_TRAINER_IDS[marker.trainer], { dimension, location } = marker.block;
    if (!id) return;
    // the one already there makes way, as a rematch calls the trainer back: a fresh trainer with no record against anyone
    for (const old of dimension.getEntities({ type: "cobblemon:rct_trainer", location, maxDistance: 48 })) if (gymTrainerOf(old) === id) old.remove();
    noteGymSite(marker.trainer, dimension, location);
    rctSpawnTrainer(dimension, { x: location.x + 0.5, y: location.y + marker.rise, z: location.z + 0.5 }, id);
}
world.afterEvents.pressurePlatePush.subscribe(({ block, source }) => {
    const player = source?.typeId === "minecraft:player" ? source : undefined;
    for (const dy of [2, 3]) {
        let m;
        try { m = gymMarker(block.dimension.getBlock({ x: block.x, y: block.y - dy, z: block.z })); } catch (e) { }
        if (!m) continue;
        if (m.role === "lift" && player) {
            const { x, y, z } = m.block.location;
            system.run(() => player.teleport({ x: x + 0.5, y: y + m.rise, z: z + 0.5 }));
        } else if (m.role === "entrance") {
            const spot = findMarker(block.dimension, m.block.location, "spot", m.trainer, 30, 3);
            system.run(() => { try { block.setType("minecraft:air"); } catch (e) { } if (spot) summonGymTrainer(spot); });
        }
        return;
    }
});
world.afterEvents.buttonPush.subscribe(({ block, source }) => {
    if (source?.typeId !== "minecraft:player") return;
    let m;
    for (const dy of [2, 3]) for (let dx = -1; dx <= 1 && !m; dx++) for (let dz = -1; dz <= 1 && !m; dz++) {
        try { const here = gymMarker(block.dimension.getBlock({ x: block.x + dx, y: block.y - dy, z: block.z + dz })); if (here?.role === "rematch") m = here; } catch (e) { }
    }
    if (!m) return;
    const id = RCT_TRAINER_IDS[m.trainer], gem = GYM_GEMS[m.trainer];
    if (!id || !gem) return;
    const inv = source.getComponent(EntityComponentTypes.Inventory)?.container;
    let slot = -1;
    for (let i = 0; i < (inv?.size ?? 0); i++) if (inv.getItem(i)?.typeId === gem) { slot = i; break; }
    const gemName = gem.slice("cobblemon:".length).split("_").map(cap).join(" ");
    if (slot < 0) { source.sendMessage(`§7You need a ${gemName} to call ${RCT_TRAINERS[id].name} back.`); return; }
    const item = inv.getItem(slot);
    if (item.amount > 1) { item.amount--; inv.setItem(slot, item); } else inv.setItem(slot);
    const spot = findMarker(block.dimension, m.block.location, "rematch_spot", m.trainer, 2, 1);
    if (spot) system.run(() => summonGymTrainer(spot));
});
// a Kanto leader's badge on the first win, as RCT's badge datapack gives it (defeat_count == 1), into the inventory
function giveGymReward(player, id) {
    const badge = GYM_BADGES[id];
    if (!badge || rctDefeats(player)[id] !== 1) return;
    const stack = new ItemStack(badge, 1);
    stack.keepOnDeath = true;   // handed out once and not craftable, so a death does not take it, like the party item
    const left = player.getComponent(EntityComponentTypes.Inventory)?.container?.addItem(stack);
    if (left) player.dimension.spawnItem(left, player.location);
    player.sendMessage(`§6${player.name} received the ${badge.slice(badge.indexOf(":") + 1).split("_").map(cap).join(" ")}!`);
}

// Battles between players (ChallengeManager, BattleConfigureGUI, BattleBuilder.pvp1v1). The player wheel's Battle opens
