        const ms = Number(event.message) || 0;
        globalThis.lagRun = ms > 0 ? system.runInterval(() => { const end = Date.now() + ms; while (Date.now() < end) { } }, 1) : undefined;
        console.warn(`[cobblemon] lag ${ms} ms a tick`);
