const HONEY_DRIP_CHANCE = 0.875;
function leafAge(block) { try { return block.permutation.getState("cobblemon:age") ?? 0; } catch (e) { return 0; } }
function setLeafAge(block, age) { try { block.setPermutation(block.permutation.withState("cobblemon:age", age)); } catch (e) { } }
function honeyDrip(block) {
    const age = leafAge(block);
    if (age <= 0 || Math.random() >= HONEY_DRIP_CHANCE) return;
    for (let i = 1; i <= 10; i++) {
        let below;
        try { below = block.dimension.getBlock({ x: block.x, y: block.y - i, z: block.z }); } catch (e) { return; }
        if (!below || below.typeId === "minecraft:air") continue;
        if (below.typeId === "cobblemon:saccharine_leaves" && leafAge(below) < 2) { setLeafAge(block, age - 1); setLeafAge(below, leafAge(below) + 1); }
        return;
    }
}
world.beforeEvents.playerInteractWithBlock.subscribe((event) => {
    const { player, block, itemStack } = event, id = itemStack?.typeId;
    if (block?.typeId !== "cobblemon:saccharine_leaves" || !["minecraft:glass_bottle", "minecraft:honey_bottle", "minecraft:bone_meal"].includes(id)) return;
    const age = leafAge(block);
    if ((id === "minecraft:glass_bottle" && age < 2) || (id !== "minecraft:glass_bottle" && age >= 2)) return;
    event.cancel = true;
    system.run(() => {
        if (!block.isValid) return;
        const creative = player.getGameMode?.() === "Creative", inv = player.getComponent("minecraft:inventory")?.container;
        const give = (item) => { try { const left = inv?.addItem(new ItemStack(item, 1)); if (left) player.dimension.spawnItem(left, player.location); } catch (e) { } };
        if (id === "minecraft:glass_bottle") {
            consumeHand(player); give("minecraft:honey_bottle"); setLeafAge(block, 0);
            try { player.dimension.playSound("bottle.fill", block.location); } catch (e) { }
        } else if (id === "minecraft:honey_bottle") {
            if (!creative) { consumeHand(player); give("minecraft:glass_bottle"); }
            setLeafAge(block, 2);
            try { player.dimension.playSound("place.honey_block", block.location); } catch (e) { }
        } else {
            if (!creative) consumeHand(player);
            setLeafAge(block, age + 1);
            try { player.dimension.spawnParticle("minecraft:crop_growth_emitter", { x: block.x + 0.5, y: block.y + 0.5, z: block.z + 0.5 }); } catch (e) { }
        }
    });
});
world.afterEvents.playerInteractWithBlock.subscribe(({ player, block, itemStack, blockFace }) => {
    if (block?.typeId !== "cobblemon:saccharine_log" || itemStack?.typeId !== "minecraft:honey_bottle") return;
    // SaccharineLogBlock.useItemOn: only a standing log (axis y) takes honey, on the side clicked, and not a side that
    // water touches
    let axisFace = "up"; try { axisFace = block.permutation.getState("minecraft:block_face") ?? "up"; } catch (e) { }
    if (axisFace !== "up" && axisFace !== "down") return;
    const facing = String(blockFace ?? "").toLowerCase();
    if (!(facing in POT_STEPS)) return;
    let front; try { front = block.dimension.getBlock({ x: block.x + POT_STEPS[facing][0], y: block.y, z: block.z + POT_STEPS[facing][1] }); } catch (e) { }
    if (front?.isLiquid) return;
    try {
        block.setPermutation(BlockPermutation.resolve("cobblemon:saccharine_log_slathered", { "minecraft:cardinal_direction": facing, "cobblemon:honey_type": Math.floor(Math.random() * 6) }));
    } catch (e) { return; }
    consumeHand(player);
    try { player.getComponent("minecraft:inventory")?.container?.addItem(new ItemStack("minecraft:glass_bottle", 1)); } catch (e) { }
    try { player.dimension.playSound("block.beehive.drip", block.location); } catch (e) { }
    saveSlathered([...slatheredLogs().filter((l) => !(l.x === block.x && l.y === block.y && l.z === block.z)), { x: block.x, y: block.y, z: block.z, d: block.dimension.id, f: facing }]);
});
world.afterEvents.entitySpawn.subscribe(({ entity, cause }) => {
    if (cause !== EntityInitializationCause.Spawned || !POKEMON[entity?.typeId]) return;
    system.runTimeout(() => {
        if (!entity.isValid || prop(entity, OWNER) !== undefined) return;
        const logs = slatheredLogs(), { x, y, z } = entity.location;
        const i = logs.findIndex((l) => l.d === entity.dimension.id && Math.hypot(l.x - x, l.y - y, l.z - z) <= SLATHER_RANGE);
        if (i < 0) return;
        const log = logs[i];
        logs.splice(i, 1); saveSlathered(logs);
        let block;
        try { block = entity.dimension.getBlock(log); } catch (e) { return; }
        if (block?.typeId !== "cobblemon:saccharine_log_slathered") return;
        const step = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] }[block.permutation.getState("minecraft:cardinal_direction") ?? log.f] ?? [0, 1];
        try { entity.teleport({ x: log.x + 0.5 + step[0] * 1.5, y: log.y, z: log.z + 0.5 + step[1] * 1.5 }); } catch (e) { }
        try { block.setPermutation(BlockPermutation.resolve("cobblemon:saccharine_log")); entity.dimension.playSound("random.burp", log); } catch (e) { }
        setProp(entity, "cobblemon:honey_drenched", true);
        const info = POKEMON[entity.typeId];
        if (Math.random() < 0.05 && info.hidden?.length) setProp(entity, "cobblemon:ability", info.hidden[Math.floor(Math.random() * info.hidden.length)]);
        const looks = VARIANT_LOOKS[entity.typeId], [form, female, shiny] = looks?.[variantOf(entity)] ?? [null, 0, 0];
        if (!shiny && Math.floor(Math.random() * 4000) === 0) {
            const n = (looks ?? []).findIndex(([f, g, sh]) => f === form && g === female && sh);
            if (n >= 0) entity.triggerEvent(`cobblemon:set_variant_${n}`);
        }
        rollAlpha(entity, 100);
    }, 5);
});
world.afterEvents.playerBreakBlock.subscribe(({ block, brokenBlockPermutation }) => {
    if (brokenBlockPermutation?.type?.id !== "cobblemon:saccharine_log_slathered") return;
    saveSlathered(slatheredLogs().filter((l) => !(l.x === block.x && l.y === block.y && l.z === block.z)));
});


// The Habitat Block (HabitatBlock, HabitatBlockEntity, ActivatedHabitatSpawning): a game master's spawner. A player in
// creative uses it to choose one of Cobblemon's habitat pools (data/cobblemon/habitat_pools) and its settings, as the
// HabitatEditGUI does: what sets it off (a redstone signal coming on, every second, or now and then as a random tick
// would), the chance an activation spawns, the range it spawns in, the most of its Pokemon alive at once and per
// activation, and a level range. A spawn takes the pool's spawns for the day's phase (the day number through the
// pool's phases) and the time of day, picks a bucket by activatedHabitatBuckets' weights, then a spawn by weight, with
// its form and a level in both ranges. It spawns only with a player within 64 blocks. The settings live in the world.
const HABITATS = "cobblemon:habitats", HABITAT_BUCKETS = { common: 83.25, uncommon: 11.25, rare: 4.125, "ultra-rare": 1.375 };
const HABITAT_TRIGGERS = ["redstone", "tick", "random_tick"];
function habitats() { try { return JSON.parse(world.getDynamicProperty(HABITATS) ?? "{}"); } catch (e) { return {}; } }
function saveHabitats(all) { world.setDynamicProperty(HABITATS, JSON.stringify(all)); }
const habitatKey = (block) => `${block.dimension.id}|${block.x}|${block.y}|${block.z}`;
const habitatSpawned = new Map();   // habitat key -> ids of its Pokemon
world.afterEvents.playerInteractWithBlock.subscribe(({ player, block }) => {
    if (block?.typeId !== "cobblemon:habitat_block") return;
    let creative = false;
    try { creative = player.getGameMode() === "Creative" || player.getGameMode() === "creative"; } catch (e) { }
    if (!creative) return;
    editHabitat(player, block);
});
function editHabitat(player, block) {
    const key = habitatKey(block), all = habitats(), now = all[key];
    const ids = Object.keys(HABITAT_POOLS).sort((a, b) => HABITAT_POOLS[a].name.localeCompare(HABITAT_POOLS[b].name));
    const form = new ActionFormData().title("Habitat Block").body(now ? `Spawning from ${HABITAT_POOLS[now.pool]?.name ?? now.pool}.` : "Choose a habitat pool to spawn from.");
    if (now) form.button("Settings").button("Turn off");
    for (const id of ids) form.button(HABITAT_POOLS[id].name);
    form.show(player).then((r) => {
        if (r.canceled) return;
        let pick = r.selection;
        if (now && pick === 0) { habitatSettings(player, block, now.pool); return; }
        if (now && pick === 1) { delete all[key]; saveHabitats(all); player.sendMessage("§7The Habitat Block is off."); return; }
        if (now) pick -= 2;
        habitatSettings(player, block, ids[pick]);
    }).catch(() => { });
}
function habitatSettings(player, block, pool) {
    const key = habitatKey(block), all = habitats(), was = all[key] ?? { trigger: "redstone", chance: 1, range: 16, max: -1, per: 1, min: 1, maxLevel: 100 };
    new ModalFormData().title(HABITAT_POOLS[pool]?.name ?? "Habitat")
        .dropdown("Trigger", ["A redstone signal", "Every second", "Now and then (random ticks)"], { defaultValueIndex: Math.max(0, HABITAT_TRIGGERS.indexOf(was.trigger)) })
        .slider("Chance per activation (%)", 1, 100, { valueStep: 1, defaultValue: Math.round(was.chance * 100) })
        .slider("Spawn range (blocks)", 2, 32, { valueStep: 1, defaultValue: was.range })
        .slider("Most alive at once (0 is no limit)", 0, 32, { valueStep: 1, defaultValue: Math.max(0, was.max) })
        .slider("Most per activation", 1, 8, { valueStep: 1, defaultValue: was.per })
        .slider("Lowest level", 1, 100, { valueStep: 1, defaultValue: was.min })
        .slider("Highest level", 1, 100, { valueStep: 1, defaultValue: was.maxLevel })
        .show(player).then((r) => {
            if (r.canceled || !r.formValues) return;
            const [t, chance, range, max, per, min, maxLevel] = r.formValues;
            const fresh = habitats();
            fresh[key] = { pool, trigger: HABITAT_TRIGGERS[t], chance: chance / 100, range, max: max || -1, per, min: Math.min(min, maxLevel), maxLevel: Math.max(min, maxLevel), power: 0 };
            saveHabitats(fresh);
            player.sendMessage(`§aThe Habitat Block spawns from ${HABITAT_POOLS[pool]?.name ?? pool}.`);
        }).catch(() => { });
}
// the pool's spawns for the day's phase and the time of day, a bucket by weight, then a spawn by weight
function habitatPick(pool, day, night) {
    const spawns = HABITAT_POOLS[pool]?.spawns ?? [];
    const phases = Math.max(1, ...spawns.flatMap((sp) => sp[5]));
    const phase = (day % phases) + 1;
    const open = spawns.filter((sp) => sp[5].includes(phase) && (sp[6] === "any" || (sp[6] === "night") === night) && speciesNamed(sp[0]));
    if (!open.length) return null;
    const buckets = [...new Set(open.map((sp) => sp[1]))];
    const bucketTotal = buckets.reduce((n, b) => n + (HABITAT_BUCKETS[b] ?? 1), 0);
    let roll = Math.random() * bucketTotal, bucket = buckets[0];
    for (const b of buckets) { roll -= HABITAT_BUCKETS[b] ?? 1; if (roll <= 0) { bucket = b; break; } }
    const inBucket = open.filter((sp) => sp[1] === bucket), total = inBucket.reduce((n, sp) => n + sp[2], 0);
    roll = Math.random() * total;
    for (const sp of inBucket) { roll -= sp[2]; if (roll <= 0) return sp; }
    return inBucket[inBucket.length - 1];
}
function activateHabitat(key, h, block) {
    if (Math.random() >= h.chance) return;
    const alive = (habitatSpawned.get(key) ?? []).filter((id) => { try { return world.getEntity(id)?.isValid; } catch (e) { return false; } });
    habitatSpawned.set(key, alive);
    const room = h.max > 0 ? Math.min(h.per, h.max - alive.length) : h.per;
    const night = (world.getTimeOfDay() % 24000) >= 12000;
    for (let n = 0; n < room; n++) {
        const sp = habitatPick(h.pool, world.getDay(), night);
        if (!sp) return;
        const typeId = speciesNamed(sp[0]), spot = spawnSpot(block.dimension, block.location, h.range, sp[7] === "grounded" ? "grounded" : "water");
        if (!typeId || !spot) continue;
        let pokemon;
        try { pokemon = block.dimension.spawnEntity(typeId, spot); } catch (e) { continue; }
        alive.push(pokemon.id);
        const lo = Math.max(sp[3], h.min), hi = Math.min(sp[4], h.maxLevel), level = lo <= hi ? ri(lo, hi) : ri(sp[3], sp[4]);
        system.run(() => {
            try {
                setProp(pokemon, LEVEL, level); setProp(pokemon, EXP, expFor(POKEMON[typeId].expGroup, level));
                setProp(pokemon, MOVESET, JSON.stringify(movesAt(formInfo(typeId, sp[8] ? variantFor(typeId, { form: sp[8] }) : 0), level)));
                if (sp[8]) applyProps(pokemon, { form: sp[8] });
            } catch (e) { }
        });
    }
}
system.runInterval(() => {
    const all = habitats();
    let changed = false;
    for (const [key, h] of Object.entries(all)) {
        const [dimId, x, y, z] = key.split("|");
        let block;
        try { block = world.getDimension(dimId).getBlock({ x: Number(x), y: Number(y), z: Number(z) }); } catch (e) { continue; }   // not loaded
        if (!block) continue;
        if (block.typeId !== "cobblemon:habitat_block") { delete all[key]; changed = true; continue; }
        if (!block.dimension.getPlayers({ location: block.location, maxDistance: 64 }).length) continue;
        if (h.trigger === "redstone") {
            let power = 0;
            try { power = block.getRedstonePower() ?? 0; } catch (e) { }
            const rising = power > 0 && !(h.power > 0);
            if ((h.power ?? 0) !== power) { h.power = power; changed = true; }
            if (rising) activateHabitat(key, h, block);
        } else if (h.trigger === "tick" || Math.random() < 1 / 68) activateHabitat(key, h, block);
    }
    if (changed) saveHabitats(all);
}, 20);

// PC box wallpapers (PCBox.wallpaper, WallpapersScrollingWidget): each box keeps its own, the default the fifth
// basic one; the six Cobblemon unlocks come from wallpaper_unlocks.molang (standing in a cave, forest or ocean biome,
// in the Nether or the End; catching an alpha, which the port has none of) and show "new" until the list is opened
const WALLS = "cobblemon:pc_walls", WALLS_UNLOCKED = "cobblemon:walls_unlocked", WALLS_UNSEEN = "cobblemon:walls_unseen";
const WALL_NAMES = { biome_cave: "Caves", biome_forest: "Forest", biome_nether: "The Nether", biome_ocean: "Ocean", biome_the_end: "The End", pokemon_alpha: "Alpha" };
function jsonProp(player, key, fallback) { try { return JSON.parse(player.getDynamicProperty(key) ?? "null") ?? fallback; } catch (e) { return fallback; } }
function wallpapersOf(player) {
    const unlocked = jsonProp(player, WALLS_UNLOCKED, []);
    return PC_WALLPAPERS.filter(([, unlock]) => !unlock || unlocked.includes(unlock));
}
function unlockWallpaper(player, unlock, playSound = true) {
    const unlocked = jsonProp(player, WALLS_UNLOCKED, []);
    if (unlocked.includes(unlock)) return;
    unlocked.push(unlock); player.setDynamicProperty(WALLS_UNLOCKED, JSON.stringify(unlocked));
    const unseen = jsonProp(player, WALLS_UNSEEN, []); unseen.push(unlock); player.setDynamicProperty(WALLS_UNSEEN, JSON.stringify(unseen));
    player.sendMessage(`§eWallpaper Unlocked §7"${WALL_NAMES[unlock] ?? unlock}"`);
    hudToast(player, "textures/blocks/cobblemon/block/functional/pc", "Wallpaper Unlocked", `"${WALL_NAMES[unlock] ?? unlock}"`, 100);   // PCStore's toast, 5 seconds
    if (playSound) try { player.playSound("cobblemon.pc.wallpaper.unlock"); } catch (e) { }
}
system.runInterval(() => {
    for (const player of world.getPlayers()) {
        const dim = player.dimension.id;
        if (dim === "minecraft:nether") unlockWallpaper(player, "biome_nether");
        if (dim === "minecraft:the_end") unlockWallpaper(player, "biome_the_end");
        let biome = "";
        try { biome = player.dimension.getBiome(player.location)?.id ?? ""; } catch (e) { continue; }
        if (/caves|deep_dark/.test(biome)) unlockWallpaper(player, "biome_cave");
        if (/forest|grove/.test(biome)) unlockWallpaper(player, "biome_forest");
        if (/ocean/.test(biome)) unlockWallpaper(player, "biome_ocean");
    }
}, 20);

// PokemonSortMode: name, level, primary type, National Pokedex number and gender (male, female, genderless), the empty
// slots last. A Pokemon out in a pasture keeps its slot, since the pasture finds it there even while far away and unloaded
const PC_SORTS = ["name", "level", "type", "pokedex_number", "gender"];
function sortBox(player, n, mode, reverse) {
    const contents = box(player, n);
    const key = (rec) => {
        const info = POKEMON[rec.t];
        switch (mode) {
            case "name": return rec.n || info?.name || "";
            case "level": return rec.lv ?? 0;
            case "type": return info?.types?.[0] ?? "";
            case "pokedex_number": return info?.dex ?? DEX_INDEX.get(rec.t) ?? 0;
            default: return ["male", "female"].indexOf(rec.k?.["cobblemon:gender"]) + 1 || 3;
        }
    };
    const loose = contents.filter((rec) => !rec?.p).sort((a, b) => {
        if (!a || !b) return (!a) - (!b);
        const x = key(a), y = key(b), c = x < y ? -1 : x > y ? 1 : 0;
        return reverse ? -c : c;
    });
    saveBox(player, n, contents.map((rec) => (rec?.p ? rec : loose.shift() ?? null)));
}

// PC Search (Search.of): the filter's words must all hold ("!" before one turns it round): holding, fainted, legendary,
// mythical, ultrabeast, or else a part of the species or the nickname, or a property as PokemonProperties reads one:
// shiny, male, female, genderless, a form (alolan, galarian...), level/lvl=N, nature=, ability=, pokeball/ball=, type=,
// friendship=N, gender=. A Pokemon that fails is not drawn and not chosen.
function pcPasses(rec, filter) {
    if (!rec || !filter) return true;
    const info = POKEMON[rec.t] ?? {};
    return filter.toLowerCase().trim().split(/\s+/).every((word) => {
        const inverted = word.startsWith("!"), w = inverted ? word.slice(1) : word;
        let ok;
        if (["holding", "helditem", "held_item"].includes(w)) ok = !!rec.k?.["cobblemon:held"];
        else if (w === "fainted") ok = !!rec.f;
        else if (w === "legendary") ok = !!info.legendary;
        else if (w === "mythical") ok = !!info.mythical;
        else if (w === "ultrabeast" || w === "ultra_beast") ok = !!info.ultraBeast;
        else if (/^(lvl|level)=\d+$/.test(w)) ok = rec.lv === Number(w.split("=")[1]);
        else ok = !w || (info.name ?? "").toLowerCase().includes(w) || (rec.n ?? "").toLowerCase().includes(w) || propertyMatches(rec, info, w);
        return inverted ? !ok : ok;
    });
}
// one PokemonProperties word against a stored Pokemon
function propertyMatches(rec, info, w) {
    const k = rec.k ?? {}, plain = (s) => String(s ?? "").toLowerCase().replace(/^cobblemon:/, "").replace(/[^a-z0-9]/g, "");
    const [key, value] = w.includes("=") ? w.split("=") : [w, undefined];
    if (value === undefined) {
        if (key === "shiny") return (SHINY_VARIANTS[rec.t] ?? []).includes(rec.v ?? 0);
        if (["male", "female", "genderless"].includes(key)) return (k["cobblemon:gender"] ?? "genderless") === key;
        const form = VARIANT_FORMS[rec.t]?.[rec.v ?? 0];
        return !!form && plain(form).startsWith(plain(key));
    }
    const v = plain(value);
    switch (key) {
        case "shiny": return (SHINY_VARIANTS[rec.t] ?? []).includes(rec.v ?? 0) === (v === "true" || v === "yes");
        case "gender": return plain(k["cobblemon:gender"] ?? "genderless") === v;
        case "nature": return plain(k["cobblemon:nature"]) === v;
        case "ability": return plain(k["cobblemon:ability"]) === v;
        case "ball": case "pokeball": return plain(k["cobblemon:caught_ball"] ?? "poke_ball").replace(/ball$/, "") === v.replace(/ball$/, "");
        case "type": return (info.types ?? []).includes(v);
        case "friendship": return Number(k["cobblemon:friendship"] ?? info.variants?.[rec.v ?? 0]?.friendship ?? info.friendship ?? 50) === Number(v);
        default: return false;
    }
}
const PC_NAMES = "cobblemon:pc_names";

function openPc(block, player, state) {
    if (battles.has(player.id)) { player.sendMessage("§cYou cannot use a PC while in battle!"); return; }
    if (!state) { tidyPastured(player); setPcScreen(block, true); state = { box: 0, sel: null }; showCosmetic.delete(player.id); try { player.playSound("cobblemon.pc.on"); } catch (e) { } }
    const done = () => { try { setPcScreen(block, false); player.playSound("cobblemon.pc.off"); } catch (e) { } };
    const party = summaryParty(player), contents = box(player, state.box);
    const walls = jsonProp(player, WALLS, {}), available = wallpapersOf(player), unseen = jsonProp(player, WALLS_UNSEEN, []);
    const names = jsonProp(player, PC_NAMES, {});
    const v = { box: names[state.box] ?? `Box ${state.box + 1}`, item: `${PC_UI}/summary/blank`, wall: walls[state.box] ?? "w05", wmode: state.wmode ? "y" : "n", opts: state.opts ? "y" : "n",
                page: state.page ?? "i", filter: state.filter ? `§f${state.filter}` : "§7Filter", rel: state.sel ? "y" : "n" };
    const sel = state.sel;
    if (sel?.kind === "box") {
        // a Pokemon stored before it rolled its IVs rolls them now and keeps them, as every Cobblemon Pokemon has them
        const contents = box(player, sel.box), rec = contents[sel.slot];
        // one out in a pasture shows what the Pokemon itself carries, since that is what comes back on recall
        if (rec?.p) {
            let out;
            try { out = player.dimension.getEntities({ families: ["owned"] }).find((e) => prop(e, OWNER) === player.id && prop(e, PASTURE_SLOT) === `${sel.box}:${sel.slot}`); } catch (e) { }
            if (out) { ivsOf(out); evsOf(out); rec.k = { ...(rec.k ?? {}), "cobblemon:ivs": prop(out, "cobblemon:ivs"), "cobblemon:evs": prop(out, "cobblemon:evs") }; saveBox(player, sel.box, contents); }
        }
        if (rec && !rec.k?.["cobblemon:ivs"]) {
            rec.k = { ...(rec.k ?? {}), "cobblemon:ivs": JSON.stringify(Object.fromEntries(STAT_KEYS.map((k) => [k, Math.floor(Math.random() * 32)]))) };
            if (!rec.k["cobblemon:evs"]) rec.k["cobblemon:evs"] = JSON.stringify(Object.fromEntries(STAT_KEYS.map((k) => [k, 0])));
            saveBox(player, sel.box, contents);
        }
        pcInfo(v, rec, null);
    }
    else if (sel?.kind === "party" && party[sel.slot]) pcInfo(v, null, party[sel.slot]);
    else pcInfo(v, null, null);
    itemSlot(v, v.held, v.cosmetic, player, `${PC_UI}/summary/blank`);
    for (let n = 0; n < 30; n++) {
        const shown = pcPasses(contents[n], state.filter);
        v[`b${n}`] = shown ? iconOf(contents[n]?.t, contents[n]?.v) : "i----"; v[`s${n}`] = sel?.kind === "box" && sel.box === state.box && sel.slot === n ? "y" : "n";
        v[`q${n}`] = contents[n]?.p && shown ? "y" : "n";
    }
    for (let n = 0; n < 6; n++) { v[`p${n}`] = iconOf(party[n]?.typeId, variantOf(party[n])); v[`s${30 + n}`] = sel?.kind === "party" && sel.slot === n ? "y" : "n"; }
    const body = PC_LAYOUT.map(([key, width]) => (width ? padBytes(v[key] ?? "", width) : v[key] ?? "")).join("");
    const form = new ActionFormData().title("cbm:pc").body(body);
    for (let n = 0; n < 36; n++) form.button("slot", `${PC_UI}/pc/slot${v[`s${n}`] === "y" ? "_on" : ""}`);
    form.button("prev", `${PC_UI}/pc/prev`).button("next", `${PC_UI}/pc/next`).button("release", `${PC_UI}/pc/${state.sel ? "release" : "none"}`).button("exit", `${PC_UI}/summary/exit`);
    form.button("options", `${PC_UI}/pc/options${state.opts ? "_on" : ""}`);
    form.button("wallpaper", `${PC_UI}/pc/${state.opts ? `set_wallpaper${state.wmode ? "_on" : ""}` : "none"}`);
    for (let n = 0; n < PC_WALLPAPERS.length; n++) {
        const w = available[n];
        // the box's own wallpaper in its alternate shows the alternate's thumbnail
        const shown = w && walls[state.box] === PC_ALT_WALLS[w[0]] ? PC_ALT_WALLS[w[0]] : w?.[0];
        form.button("wall", `${PC_UI}/pc/${w ? `wps_${shown}${w[1] && unseen.includes(w[1]) ? "_new" : ""}` : "none"}`);
    }
    // the sort buttons show their reverse face after a sort by them, as a shift-click would sort
    // each sort button's text is its tooltip (lang ui.sort.*)
    const SORT_TIPS = { name: "Sort by name", level: "Sort by level", type: "Sort by type", pokedex_number: "Sort by Pok\u00e9dex number", gender: "Sort by gender" };
    for (const mode of PC_SORTS) form.button(state.opts ? SORT_TIPS[mode] : "", `${PC_UI}/pc/${state.opts ? `sort_${mode}${state.sorted === mode ? "_reverse" : ""}` : "none"}`);
    form.button("info page", `${PC_UI}/pc/info_arrow`);
    form.button("filter", `${PC_UI}/pc/bar`).button("box name", `${PC_UI}/pc/bar`);
    // the hover areas: the filter's icon (its format, lang ui.pc.filter.tooltip) and the held item (its name)
    form.button("Format: pikachu shiny held_item lvl=1...", `${PC_UI}/pc/none`).button(v.itemName ?? "", `${PC_UI}/pc/none`);
    form.button("item toggle", `${PC_UI}/summary/itog_${v.imode === "c" ? "h" : "c"}`);
    form.show(player).then((r) => {
        if (r.canceled || r.selection === 39) { done(); return; }
        const pick = r.selection, again = (delay = 0) => system.runTimeout(() => openPc(block, player, state), delay);
        if (pick === 36 || pick === 37) { state.box = (state.box + (pick === 37 ? 1 : pcBoxes(player) - 1)) % pcBoxes(player); again(); return; }
        if (pick === 38) { pcRelease(player, state, party, () => again(5)); return; }
        if (pick === 40) { state.opts = !state.opts; if (!state.opts) state.wmode = false; again(); return; }
        if (pick === 41) {
            if (state.opts) { state.wmode = !state.wmode; if (state.wmode) player.setDynamicProperty(WALLS_UNSEEN, "[]"); }
            again(); return;
        }
        if (pick === 47 + PC_WALLPAPERS.length + PC_SORTS.length) {   // the held and cosmetic item toggle
            if (showCosmetic.has(player.id)) showCosmetic.delete(player.id); else showCosmetic.add(player.id);
            try { player.playSound("cobblemon.gui.click"); } catch (e) { }
            again(); return;
        }
        if (pick >= 45 + PC_WALLPAPERS.length + PC_SORTS.length) { again(); return; }   // the tooltips' hover areas
        if (pick === 43 + PC_WALLPAPERS.length + PC_SORTS.length || pick === 44 + PC_WALLPAPERS.length + PC_SORTS.length) {
            // TextWidget's 19 characters: the filter, or the box's name (an empty one gives the box its number back)
            const naming = pick === 44 + PC_WALLPAPERS.length + PC_SORTS.length;
            new ModalFormData().title(naming ? "Box Name" : "Filter")
                .textField(naming ? "Name" : "Format: pikachu shiny held_item lvl=1...", "", { defaultValue: naming ? names[state.box] ?? "" : state.filter ?? "" })
                .show(player).then((q) => {
                    if (!q.canceled) {
                        const text = String(q.formValues?.[0] ?? "").replace(/[%§]/g, "").trim().slice(0, 19);
                        if (naming) { if (text) names[state.box] = text; else delete names[state.box]; player.setDynamicProperty(PC_NAMES, JSON.stringify(names)); }
                        else { state.filter = text || undefined; state.sel = null; }
                    }
                    again();
                }).catch(done);
            return;
        }
        if (pick === 42 + PC_WALLPAPERS.length + PC_SORTS.length) {
            // the arrow turns the info box: info, IVs, EVs
            state.page = { i: "v", v: "e", e: "i" }[state.page ?? "i"];
            again(); return;
        }
        if (pick >= 42 + PC_WALLPAPERS.length) {
            const mode = PC_SORTS[pick - 42 - PC_WALLPAPERS.length];
            if (state.opts && mode) {
                // a second press of the same button sorts the other way, where Cobblemon's is a shift-click
                const reverse = state.sorted === mode;
                sortBox(player, state.box, mode, reverse);
                state.sorted = reverse ? null : mode; state.sel = null;
                try { player.playSound("cobblemon.pc.click"); } catch (e) { }
            }
            again(); return;
        }
        if (pick >= 42) {
            const w = available[pick - 42];
            // the wallpaper the box already has, chosen again, turns to its alternate and back (Cobblemon's shift-click)
            const alt = PC_ALT_WALLS[w?.[0]], now = walls[state.box] ?? "w05";
            if (w) { walls[state.box] = alt && now === w[0] ? alt : w[0]; player.setDynamicProperty(WALLS, JSON.stringify(walls)); try { player.playSound("cobblemon.pc.click"); } catch (e) { } }
            again(); return;
        }
        const target = pick < 30 ? { kind: "box", box: state.box, slot: pick } : { kind: "party", slot: pick - 30 };
        if (target.kind === "box" && !pcPasses(contents[target.slot], state.filter)) { again(); return; }
        const occupied = target.kind === "box" ? !!contents[target.slot] : !!party[target.slot];
        // pc.grab as a Pokemon is picked up, pc.drop as it is put down (PCGUI's sounds)
        if (!sel) { state.sel = occupied ? target : null; if (occupied) try { player.playSound("cobblemon.pc.grab"); } catch (e) { } again(); return; }
        if (sel.kind === target.kind && sel.slot === target.slot && (sel.kind === "party" || sel.box === target.box)) { state.sel = null; try { player.playSound("cobblemon.pc.drop"); } catch (e) { } again(); return; }
        state.sel = null;
        try { player.playSound("cobblemon.pc.drop"); } catch (e) { }
        pcMove(player, sel, target);
        again(2);
    }).catch(done);
}

// moves the selected Pokemon to a slot: within the PC or the party it swaps, between the two it deposits and withdraws,
// in its ball (one out comes back to it first)
function pcMove(player, from, to) {
    const slots = partyOf(player.id);
    const here = (pos) => (pos.kind === "box" ? box(player, pos.box)[pos.slot] : slots[pos.slot]);
    const a = here(from), b = here(to);
    if ((from.kind === "box" && a?.p) || (to.kind === "box" && b?.p)) { player.sendMessage("§7That Pokemon is out in a pasture. Bring it back there first."); return; }
    if (from.kind === "box" && to.kind === "box") {
        const src = box(player, from.box), dst = from.box === to.box ? src : box(player, to.box);
        const moving = src[from.slot]; src[from.slot] = dst[to.slot]; dst[to.slot] = moving;
        saveBox(player, from.box, src); if (dst !== src) saveBox(player, to.box, dst);
        return;
    }
    if (from.kind === "party" && to.kind === "party") {
        const i = from.slot, j = Math.min(to.slot, slots.length - 1);
        [slots[i], slots[j]] = [slots[j], slots[i]]; saveParty(player.id);
        return;
    }
    const [boxPos, partyPos] = from.kind === "box" ? [from, to] : [to, from];
    const contents = box(player, boxPos.box), rec = contents[boxPos.slot], slot = slots[partyPos.slot];
    if (slot?.out) recallMember(player, slot);
    contents[boxPos.slot] = slot ? slot.rec : null;
    saveBox(player, boxPos.box, contents);
    if (slot && rec) { slot.rec = rec; slot.pid = newPid(); slot.out = null; saveParty(player.id); }
    else if (slot) removeMember(player, slot);
    else if (rec) slots.push({ pid: newPid(), rec, out: null }), saveParty(player.id);
}

function pcRelease(player, state, party, then) {
    const sel = state.sel;
    if (!sel) { then(); return; }
    const rec = sel.kind === "box" ? box(player, sel.box)[sel.slot] : null, slot = sel.kind === "party" ? partyOf(player.id)[sel.slot] : null;
    if (!rec && !slot) { state.sel = null; then(); return; }
    if (rec?.p) { player.sendMessage("§7That Pokemon is out in a pasture. Bring it back there first."); then(); return; }
    // preventCompletePartyDeposit is false in Cobblemon's config: the last party Pokemon can be released too
    const label = describe(rec ?? slot.rec);
    new MessageFormData().title("Release").body(`Release ${label}? It will be gone for good.`).button1("Keep").button2("Release")
        .show(player).then((r) => {
            if (r.selection === 1) {
                if (rec) { const contents = box(player, sel.box); contents[sel.slot] = null; saveBox(player, sel.box, contents); }
                else removeMember(player, slot);
                player.sendMessage(`§7${label} was released. Bye-bye!`);
                state.sel = null;
            }
            then();
        }).catch(then);
}

function deposit(player, done) {
    const party = mine(player, 32);
    if (!party.length) { player.sendMessage("§7None of your Pokemon are nearby."); done(); return; }
    const form = new ActionFormData().title("Deposit which Pokemon?");
    for (const e of party) form.button(describe(snapshot(e)));
    form.show(player).then((r) => {
        if (r.canceled || !party[r.selection]?.isValid) { done(); return; }
        const entity = party[r.selection];
        for (let n = 0; n < pcBoxes(player); n++) {
            const contents = box(player, n), slot = contents.indexOf(null);
            if (slot < 0) continue;
            contents[slot] = snapshot(entity);
            saveBox(player, n, contents);
            player.sendMessage(`§a${describe(contents[slot])} went to Box ${n + 1}.`);
            recallEffect(player, entity, () => { try { entity.remove(); } catch (e) { } });
            done();
            return;
        }
        player.sendMessage("§cYour PC is full."); done();
    }).catch(done);
}

function pickStored(player, action, then, done) {
    const boxes = [];
    for (let n = 0; n < pcBoxes(player); n++) { const c = box(player, n).filter(Boolean).length; if (c) boxes.push([n, c]); }
    if (!boxes.length) { player.sendMessage("§7Your PC is empty."); done(); return; }
    const form = new ActionFormData().title(`${action}: which box?`);
    for (const [n, c] of boxes) form.button(`Box ${n + 1}\n§7${c}/${PER_BOX}`);
    form.show(player).then((r) => {
        if (r.canceled) { done(); return; }
        const n = boxes[r.selection][0], contents = box(player, n);
        const slots = contents.map((rec, i) => [rec, i]).filter(([rec]) => rec);
        const list = new ActionFormData().title(`Box ${n + 1}: ${action.toLowerCase()} which?`);
        for (const [rec] of slots) list.button(describe(rec));
        list.show(player).then((q) => { if (q.canceled) done(); else then(n, slots[q.selection][1]); }).catch(done);
    }).catch(done);
}

function withdraw(player, n, slot, done) {
    if (partyOf(player.id).length >= PARTY_SIZE) { player.sendMessage(`§cYou already have ${PARTY_SIZE} Pokemon with you.`); done(); return; }
    const contents = box(player, n), rec = contents[slot];
    if (!rec) { done(); return; }
    if (rec.p) { player.sendMessage("§7That Pokemon is out in a pasture. Bring it back there first."); done(); return; }
    const d = player.getViewDirection(), at = { x: player.location.x + d.x * 2, y: player.location.y, z: player.location.z + d.z * 2 };
    try { spawnStored(player, rec, at); } catch (e) { player.sendMessage("§cThat Pokemon could not come out here."); done(); return; }
    contents[slot] = null; saveBox(player, n, contents);
    player.sendMessage(`§aGo, ${describe(rec)}!`);
    done();
}

function release(player, n, slot, done) {
    const contents = box(player, n), rec = contents[slot];
    if (!rec) { done(); return; }
    if (rec.p) { player.sendMessage("§7That Pokemon is out in a pasture. Bring it back there first."); done(); return; }
    new MessageFormData().title("Release").body(`Release ${describe(rec)}? It will be gone for good.`).button1("Keep").button2("Release")
        .show(player).then((r) => {
            if (r.selection === 1) { contents[slot] = null; saveBox(player, n, contents); player.sendMessage(`§7${describe(rec)} was released. Bye-bye!`); try { player.playSound("cobblemon.pc.release"); } catch (e) { } }
            done();
        }).catch(done);
}

// The pasture. As in Cobblemon, a pastured Pokemon stays in its PC box and is out in the world at the same time,
// wandering within 32 blocks of the pasture; up to 16 per pasture (defaultPasturedPokemonLimit). Using the pasture
// lists the player's PC Pokemon to send out and the ones it already has to bring back; a PC slot that is out shows
// as pastured and cannot be withdrawn or released until it is back. Breaking the pasture brings them all back.
const PASTURE_LIMIT = 16, PASTURE_SLOT = "cobblemon:pc_slot", PASTURE_AT = "cobblemon:pasture", OWNER_NAME = "cobblemon:owner_name";
const pastureViewers = new Map();   // player id -> the pasture block whose screen they have open (PastureLinkManager's links)

// PokemonPastureBlockEntity.canAddPokemon's crowding limit: no more go out while the 32 block square round the pasture
// (pastureMaxWanderDistance wide, at any height) holds pastureMaxPerChunk (4) Pokemon for each of its 4 by 4 chunks
const PASTURE_CROWD = 4 * 4 * 4;
function pastureCrowded(block) {
    const { x, z } = block.location, { min, max } = block.dimension.heightRange;
    let near = [];
    try { near = block.dimension.getEntities({ location: { x: x + 0.5 - 16, y: min, z: z + 0.5 - 16 }, volume: { x: 32, y: max - min, z: 32 } }); } catch (e) { return false; }
    return near.filter((e) => POKEMON[e.typeId]).length >= PASTURE_CROWD;
}
function pastureKey(block) {
    const bottom = block.permutation.getState("cobblemon:part") === "top" ? block.below() : block;
    return keyOf(bottom.dimension, bottom.location);
}

function pasturedHere(dimension, key, location) {
    return dimension.getEntities({ families: ["owned"], location, maxDistance: 80 }).filter((e) => prop(e, PASTURE_AT) === key);
}

// a PC slot marked as pastured whose Pokemon is gone (its pasture broken while the player was away) comes back
function tidyPastured(player) {
    for (let n = 0; n < pcBoxes(player); n++) {
        const contents = box(player, n);
        let changed = false;
        contents.forEach((rec, i) => {
            if (!rec?.p) return;
            const [dimId, pos] = rec.p.split("|"), [x, y, z] = pos.split(",").map(Number);
            let block;
            try { block = world.getDimension(dimId).getBlock({ x, y, z }); } catch (e) { return; }   // unloaded: leave it
            if (block && block.typeId !== "cobblemon:pasture") { delete rec.p; changed = true; }
        });
        if (changed) saveBox(player, n, contents);
    }
}

// sends a stored Pokemon out as the player's own; used by the PC and the pasture
function spawnStored(player, rec, at) {
    const entity = player.dimension.spawnEntity(rec.t, at);
    system.run(() => {
        try { entity.triggerEvent(`cobblemon:set_variant_${rec.v}`); } catch (e) { }
        try {
            entity.triggerEvent("cobblemon:caught");
            entity.getComponent(EntityComponentTypes.Tameable)?.tame(player);
            setProp(entity, OWNER, player.id); setProp(entity, LEVEL, rec.lv); setProp(entity, EXP, rec.xp);
            if (rec.mv) setProp(entity, MOVESET, rec.mv);
            if (rec.f) setProp(entity, FAINTED, true);
            if (rec.n) setProp(entity, NICK, rec.n);
            for (const [key, value] of Object.entries(rec.k ?? {})) setProp(entity, key, value);
            const h = entity.getComponent(EntityComponentTypes.Health);
            if (h) h.setCurrentValue(Math.max(1, Math.round(h.effectiveMax * rec.hp)));
        } catch (e) { }
        sendOutEffect(player, entity);
    });
    return entity;
}

function setPastureLamp(block, on) {
    const top = block.permutation.getState("cobblemon:part") === "top" ? block : block.above();
    if (top?.typeId === "cobblemon:pasture") setState(top, "cobblemon:on", on);
}

// The pasture, laid out by ui/server_form.json as Cobblemon's PC with the pasture panel in place of the party: choose a
// Pokemon in a box, then a row of the pasture list, to send it out; choose one of your own rows to bring it back; Recall
// All brings back all of yours. The list shows four rows at a time; the count above it turns the page.
const CONFLICT = "cobblemon:pasture_conflict", DEFENDERS_SET = new Set(DEFENDERS);
// AttackHostileMobsTask leaves out slimes (magma cubes too), piglins and creepers
const NOT_ATTACKED = ["minecraft:slime", "minecraft:magma_cube", "minecraft:piglin", "minecraft:piglin_brute", "minecraft:creeper"];
// AttackHostileMobsTask for a pastured Pokemon with the defend toggle on: it takes the nearest hostile mob it can reach
// within 16 blocks, keeping to the pasture's roaming range (the tether), goes to it and strikes it once a second for its
// attack damage (meleeDamage, attackToDamageCurve of its Attack). DefendOwnerTask for one with its trainer: it goes for
// the mob that last hurt its trainer (DefendOwnerSensor's lastHurtMob; never a player) among the living entities it
// senses, within its FOLLOW_RANGE of 32 blocks, for as long as that mob lives (no time limit: lastHurtMob is kept until
// the mob dies). The entity's own targeting proved unreliable, so the script drives both.
const DEFEND_RANGE = 32;   // PokemonEntity's FOLLOW_RANGE, the nearest_living_entities sensor's reach
const lastStrike = new Map(), ownerAttacker = new Map();   // player id -> { id }
// An owned Pokemon brought to 0 health in the world (a fall, a mob, lava) faints, as PokemonEntity.hurt sets
// currentHealth to 0 and the Pokemon stays in its trainer's party; here the entity is the Pokemon, so the record taken
// as it is hurt brings it back beside its trainer, fainted. A /kill still removes it.
const lastRecord = new Map();   // entity id -> its record as of its last hurt
world.afterEvents.entityHurt.subscribe(({ hurtEntity }) => {
    if (!POKEMON[hurtEntity?.typeId] || !prop(hurtEntity, OWNER)) return;
    try { lastRecord.set(hurtEntity.id, { rec: prop(hurtEntity, PID) ? partySnapshot(hurtEntity) : snapshot(hurtEntity), pid: prop(hurtEntity, PID), owner: prop(hurtEntity, OWNER), at: { ...hurtEntity.location }, dim: hurtEntity.dimension }); } catch (e) { }
});
world.afterEvents.entityDie.subscribe(({ deadEntity, damageSource }) => {
    const kept = lastRecord.get(deadEntity?.id);
    lastRecord.delete(deadEntity?.id);
    if (!kept || damageSource?.cause === "override" || damageSource?.cause === "selfDestruct") return;
    const rec = { ...kept.rec, f: true, hp: 0, k: { ...(kept.rec.k ?? {}), [FAINTED]: true } };
    const owner = world.getPlayers().find((p) => p.id === kept.owner);
    const name = rec.n || POKEMON[rec.t]?.name || "Your Pokemon";
    const slot = kept.pid && partyOf(kept.owner).find((s) => s.pid === kept.pid);
    if (slot) {
        delete rec.k[FAINTED];
        slot.rec = rec; slot.out = null; saveParty(kept.owner);
        owner?.sendMessage(`§c${name} fainted!`);
        return;
    }
    system.run(() => {
        try {
            if (owner) { spawnStored(owner, rec, owner.location); owner.sendMessage(`§c${name} fainted!`); }
            // a trainer who is not here: it stays where it fell, theirs and staying, until they come back
            else spawnForParticipant({ id: kept.owner, name: rec.k?.[OWNER_NAME] ?? kept.owner, bot: { dimension: kept.dim } }, rec, kept.at);
        } catch (e) { console.warn(`[cobblemon] could not bring back a fainted ${rec.t}: ${e}`); }
    });
});
world.afterEvents.entityHurt.subscribe(({ hurtEntity, damageSource }) => {
    const by = damageSource?.damagingEntity;
    if (hurtEntity?.typeId !== "minecraft:player" || !by?.isValid || by.typeId === "minecraft:player" || POKEMON[by.typeId]) return;
    ownerAttacker.set(hurtEntity.id, { id: by.id });
});
system.runInterval(() => {
    for (const dim of ["overworld", "nether", "the_end"]) {
        let owned = [];
        try { owned = world.getDimension(dim).getEntities({ families: ["owned"] }); } catch (e) { continue; }
        for (const e of owned) {
            if (prop(e, FAINTED) || !DEFENDERS_SET.has(e.typeId)) continue;
            let foe;
            if (prop(e, PASTURE_AT)) {
                if (!prop(e, CONFLICT)) continue;
                const [, pos] = String(prop(e, PASTURE_AT)).split("|"), home = (pos ?? "").split(",").map(Number);
                let foes = [];
                try { foes = e.dimension.getEntities({ families: ["monster"], excludeTypes: NOT_ATTACKED, location: e.location, maxDistance: 16 }); } catch (err) { continue; }
                const near = (a) => (home.length === 3 ? Math.hypot(a.location.x - home[0], a.location.z - home[2]) <= 32 : true);
                foe = foes.filter(near).sort((a, b) => dist(a, e) - dist(b, e))[0];
            } else {
                // with its trainer, out of battle: the mob that last hurt them
                let inBattle = false;
                try { inBattle = !!e.getProperty("cobblemon:battle"); } catch (err) { }
                const hit = ownerAttacker.get(prop(e, OWNER));
                if (inBattle || !hit) continue;
                const attacker = world.getEntity(hit.id);
                if (!isAlive(attacker)) { ownerAttacker.delete(prop(e, OWNER)); continue; }
                if (defendsAgainst(e, attacker)) foe = attacker;
            }
            if (foe) chaseAndStrike(e, foe);
        }
    }
    predation();
}, 4);
// a mob that hurt the trainer is fought while it is alive, in the Pokemon's dimension and within DEFEND_RANGE of it
function defendsAgainst(e, attacker) { return isAlive(attacker) && attacker.dimension.id === e.dimension.id && dist(attacker, e) <= DEFEND_RANGE; }
function isAlive(e) {
    if (!e?.isValid) return false;
    try { return (e.getComponent(EntityComponentTypes.Health)?.currentValue ?? 1) > 0; } catch (err) { return true; }
}
// PokemonServerDelegate.attackToDamageCurve: the ATTACK_DAMAGE of a melee hit, ceil(sqrt((Attack - 10) ^ 0.875)) and at
// least 1, from the Pokemon's own Attack stat at its level (Rattata at level 5 hits for 2, Snorlax at 50 for 9)
function attackDamage(attack) { return attack < 10 ? 1 : Math.max(1, Math.ceil(Math.sqrt(Math.pow(attack - 10, 0.875)))); }
function meleeDamage(e) {
    const species = POKEMON[e.typeId];
    if (!species) return 1;
    let variant = 0;
    try { variant = e.getComponent("minecraft:variant")?.value ?? 0; } catch (err) { }
    const info = { ...species, ...(species.variants?.[variant] ?? {}) };
    return attackDamage(statsOf(e, info, prop(e, LEVEL) ?? info.level).atk);
}
// a step toward the foe, turned to face it, and within reach a strike once a second for its attack damage
function chaseAndStrike(e, foe) {
    const d = dist(foe, e);
    if (d > 1.8) {
        const k = Math.min(0.45, d - 1.5) / d;
        try { e.tryTeleport({ x: e.location.x + (foe.location.x - e.location.x) * k, y: e.location.y, z: e.location.z + (foe.location.z - e.location.z) * k },
                            { facingLocation: foe.location, checkForBlocks: true, keepVelocity: true }); } catch (err) { }
    } else if (system.currentTick - (lastStrike.get(e.id) ?? -99) >= 20) {
        lastStrike.set(e.id, system.currentTick);
        try { foe.applyDamage(meleeDamage(e), { cause: EntityDamageCause.entityAttack, damagingEntity: e }); } catch (err) { }
    }
}
