    if (spawn.maxLureLevel !== undefined && cast.lure > spawn.maxLureLevel) return false;
    if (spawn.minY !== undefined && at.y < spawn.minY) return false;
    if (spawn.maxY !== undefined && at.y > spawn.maxY) return false;
