    const target = st.target?.isValid ? st.target : null;
    const seg = st.progress > 0 && st.progress >= 20 ? Math.max(0, Math.min(40, Math.floor((st.progress - 20) / 2))) : 40;
    let sides = "xxxx", texts = Array(8).fill(""), own = "", caught = "n";
